-- surface: literal.integer
SELECT -9223372036854775808 AS lo, 9223372036854775807 AS hi;

-- surface: literal.decimal
SELECT CAST('99999999999999999999999999999999999999' AS DECIMAL(38,0)) AS value;

-- surface: literal.decimal256
SELECT arrow_cast('1234567890123456789012345678901234567890', 'Decimal256(40, 0)') AS value;

-- surface: literal.boolean
SELECT TRUE AS yes, FALSE AS no, CAST(NULL AS BOOLEAN) AS unknown;

-- surface: literal.string
SELECT 'O''Brien' AS quoted, 'naïve 日本語' AS unicode, '' AS empty;

-- surface: literal.escape
SELECT E'line1\nline2\t\\' AS value;

-- surface: literal.date
SELECT DATE '1969-12-31' AS value;

-- surface: literal.time
SELECT TIME '12:34:56' AS value;

-- surface: literal.timestamp
SELECT TIMESTAMP '1969-12-31 23:59:59.123456789' AS value;

-- surface: literal.interval
SELECT CAST(INTERVAL '1 day 2 hours' AS VARCHAR) AS value;

-- surface: literal.binary
SELECT decode('0001ff', 'hex') AS value;

-- surface: literal.empty_array
SELECT CAST([] AS BIGINT[]) AS value;

-- surface: literal.null_array
SELECT CAST(NULL AS BIGINT[]) AS value;

-- surface: literal.try_cast
SELECT TRY_CAST('bad' AS BIGINT) AS value;

-- surface: literal.case_coercion
SELECT CASE WHEN TRUE THEN CAST(1.23 AS DECIMAL(6,2)) ELSE 0 END AS value;

-- surface: literal.nullif_coercion
SELECT nullif(CAST(1.25 AS DECIMAL(6,2)), 0) AS value;
